if "hr_page" not in st.session_state:
    st.session_state.hr_page = "Home"


def get_user():
    user = None
    try:
        user = current_user()
    except Exception:
        user = None

    if not user:
        user = st.session_state.get("hr_user")

    if not user:
        return None

    try:
        user = dict(user)
    except Exception:
        pass

    username = str(user.get("username", "")).strip().lower()
    if username in ADMIN_USERS:
        user["role"] = "admin"
        user.setdefault("full_name", ADMIN_USERS[username])

    st.session_state["hr_user"] = user
    return user


def set_logged_user(user):
    try:
        user = dict(user)
    except Exception:
        pass

    username = str(user.get("username", "")).strip().lower()
    if username in ADMIN_USERS:
        user["role"] = "admin"
        user.setdefault("full_name", ADMIN_USERS[username])

    st.session_state["hr_user"] = user
    st.session_state["hr_page"] = "Home"


def clear_logged_user():
    for key in ["hr_user", "hr_logged_in", "logged_in", "user"]:
        st.session_state.pop(key, None)
    st.session_state["hr_page"] = "Home"


def require_user():
    user = get_user()
    if not user:
        st.warning("Please log in first.")
        st.stop()
    return user


def require_admin():
    user = require_user()
    if str(user.get("role", "user")).strip().lower() != "admin":
        st.error("Administrator access is required for this section.")
        st.stop()
    return user


def do_logout():
    try:
        logout_user()
    finally:
        clear_logged_user()
        st.rerun()


