def render_login():
    # Keep the login page compact: place the V-TRAIN logo and
    # authentication controls in the left sidebar, matching
    # the sidebar layout used after login.
    with st.sidebar:
        st.markdown(
            '<div class="sidebar-logo-wrap sidebar-login-logo">',
            unsafe_allow_html=True,
        )
        st.image(get_vtrain_logo(), width=100)
        st.markdown('</div>', unsafe_allow_html=True)

        st.markdown(
            '<div class="sidebar-brand-title">HR Training Dashboard</div>',
            unsafe_allow_html=True,
        )

        st.markdown(
            '<div class="sidebar-section">ACCOUNT ACCESS</div>',
            unsafe_allow_html=True,
        )

        login_tab, signup_tab = st.tabs(
            ["🔐 Log in", "👤 Create account"]
        )

        with login_tab:
            st.markdown(
                '<div class="auth-heading">Welcome back</div>',
                unsafe_allow_html=True,
            )

            with st.form("login_form"):
                identifier = st.text_input(
                    "Username or email",
                    placeholder="Enter username or email",
                )
                password = st.text_input(
                    "Password",
                    type="password",
                    placeholder="Enter password",
                )
                submitted = st.form_submit_button(
                    "Log in",
                    type="primary",
                    use_container_width=True,
                )

            if submitted:
                if not identifier.strip() or not password:
                    st.error(
                        "Please enter both username/email and password."
                    )
                else:
                    try:
                        user = authenticate(
                            identifier.strip(), password
                        )
                        if user:
                            login_user(user)
                            set_logged_user(user)
                            st.rerun()
                        else:
                            st.error(
                                "Invalid username/email or password."
                            )
                    except Exception:
                        st.error(
                            "Unable to log in. Please try again."
                        )

        with signup_tab:
            st.markdown(
                '<div class="auth-heading">'
                'Create your account'
                '</div>',
                unsafe_allow_html=True,
            )

            with st.form("signup_form"):
                full_name = st.text_input(
                    "Full name",
                    placeholder="e.g. Samoda De Silva",
                )
                username = st.text_input(
                    "Username",
                    placeholder="e.g. samoda",
                )
                email = st.text_input(
                    "Email",
                    placeholder="name@company.com",
                )
                password = st.text_input(
                    "Password",
                    type="password",
                    placeholder="Minimum 8 characters",
                )
                confirm = st.text_input(
                    "Confirm password",
                    type="password",
                )
                submitted = st.form_submit_button(
                    "Create account",
                    type="primary",
                    use_container_width=True,
                )

            if submitted:
                full_name = full_name.strip()
                username = username.strip().lower()
                email = email.strip().lower()

                if not full_name:
                    st.error("Please enter your full name.")
                elif not re.fullmatch(
                    r"[a-z0-9._-]{3,50}", username
                ):
                    st.error(
                        "Username must contain 3–50 lowercase "
                        "letters, numbers, dots, underscores or hyphens."
                    )
                elif not re.fullmatch(
                    r"[^@\s]+@[^@\s]+\.[^@\s]+", email
                ):
                    st.error(
                        "Please enter a valid email address."
                    )
                elif len(password) < 8:
                    st.error(
                        "Password must contain at least 8 characters."
                    )
                elif password != confirm:
                    st.error("Passwords do not match.")
                else:
                    try:
                        create_user(
                            username=username,
                            email=email,
                            full_name=full_name,
                            password=password,
                        )
                        st.success(
                            "Account created successfully. "
                            "Please use the Log in tab."
                        )
                    except ValueError as e:
                        st.error(str(e))
                    except Exception:
                        st.error(
                            "Unable to create the account. "
                            "Please check the database connection."
                        )

    # ------------------------------------------------------------
    # KDU-style login hero carousel
    # ------------------------------------------------------------
    if "login_slide" not in st.session_state:
        st.session_state.login_slide = 0

    staff_image = Path("Staff.png")
    staff_image_base64 = ""
    if staff_image.exists():
        staff_image_base64 = base64.b64encode(
            staff_image.read_bytes()
        ).decode("ascii")

    login_slides = [
        {
            "src": f"data:image/png;base64,{staff_image_base64}",
            "caption": "V-TRAIN — Building a Skilled Workforce",
            "available": bool(staff_image_base64),
        },
        {
            "src": f"data:image/png;base64,{HR_LEADERSHIP_IMAGE_BASE64}",
            "caption": "Vidulanka PLC — People & Leadership",
            "available": True,
        },
        {
            "src": f"data:image/png;base64,{VIDULANKA_TEAM_IMAGE_BASE64}",
            "caption": "Vidulanka PLC — Our People, Our Strength",
            "available": True,
        },
    ]

    available_slides = [s for s in login_slides if s["available"]]

    if available_slides:
        slide_index = st.session_state.login_slide % len(available_slides)
        ordered_slides = available_slides[slide_index:] + available_slides[:slide_index]

        if st.button("‹", key="login_carousel_prev", help="Previous image"):
            st.session_state.login_slide = (slide_index - 1) % len(available_slides)
            st.rerun()

        st.markdown('<div class="login-page-lock"></div>', unsafe_allow_html=True)

        slides_html = ""
        for i, item in enumerate(ordered_slides):
            delay = i * 5
            slides_html += f'''<div class="login-slide" style="animation-delay:{delay}s;">
                <img class="login-carousel-image" src="{item["src"]}" alt="Vidulanka PLC HR Training hero image" />
                <div class="login-carousel-caption">{item["caption"]}</div>
            </div>'''

        st.markdown(
            f'''<div class="login-carousel-wrap">
                <div class="login-carousel-track">{slides_html}</div>
                <div class="login-carousel-dots"><span>●</span><span>●</span><span>●</span></div>
            </div>''',
            unsafe_allow_html=True,
        )

        if st.button("›", key="login_carousel_next", help="Next image"):
            st.session_state.login_slide = (slide_index + 1) % len(available_slides)
            st.rerun()

    # ------------------------------------------------------------
    # V-TRAIN AI assistant
    # ------------------------------------------------------------
    with st.popover("🤖 V-TRAIN AI"):
        st.markdown("### V-TRAIN AI Assistant")
        st.caption("Quick help for the HR Training Dashboard")

        question = st.selectbox(
            "How can I help?",
            [
                "Select a topic",
                "How do I log in?",
                "Where do I enter training data?",
                "Where can I enter the annual budget?",
                "What can the dashboard show?",
                "Where is the Worker Master?",
            ],
        )

        answers = {
            "How do I log in?":
                "Use your registered username/email and password in the "
                "Log in tab. If you do not have an account, use Create account.",
            "Where do I enter training data?":
                "After logging in, open Data Entry from the sidebar or Home "
                "page and add the training programme details.",
            "Where can I enter the annual budget?":
                "Open Budget Entry from the sidebar or Home page to enter "
                "annual training budgets by location and category.",
            "What can the dashboard show?":
                "The dashboard provides training KPIs, trends, costs, "
                "training hours and Budget vs Actuals.",
            "Where is the Worker Master?":
                "After logging in, use the Worker Master page from the "
                "sidebar to manage worker information.",
        }

        if question != "Select a topic":
            st.info(answers[question])


