def render_account():
    user = require_user()

    st.title("My Account")

    with st.container(border=True):
        st.write(
            f"**Name:** "
            f"{user.get('full_name', user.get('name', ''))}"
        )
        st.write(
            f"**Username:** @{user.get('username', '')}"
        )
        st.write(
            f"**Email:** {user.get('email', '')}"
        )
        st.write(
            f"**Role:** "
            f"{str(user.get('role', 'user')).title()}"
        )

    st.write("")

    with st.container(border=True):
        st.subheader("Change Password")

        with st.form("change_password_form"):
            new_password = st.text_input(
                "New password",
                type="password",
            )
            confirm = st.text_input(
                "Confirm new password",
                type="password",
            )
            submit = st.form_submit_button(
                "Update password",
                type="primary",
            )

        if submit:
            if len(new_password) < 8:
                st.error(
                    "Password must contain at least 8 characters."
                )
            elif new_password != confirm:
                st.error(
                    "Passwords do not match."
                )
            else:
                try:
                    change_password(
                        int(user["id"]),
                        new_password,
                    )
                    st.success(
                        "Password updated successfully."
                    )
                except Exception:
                    st.error(
                        "Unable to update the password."
                    )


# ============================================================
# MAIN
# ============================================================

logged_user = get_user()

if not logged_user:
    render_login()
else:
    render_sidebar()

    page = st.session_state.get(
        "hr_page",
        "Home",
    )

    if page == "Home":
        render_home()
    elif page == "Dashboard":
        render_dashboard()
    elif page == "Data Entry":
        render_data_entry()
    elif page == "Import Excel":
        render_import_excel()
    elif page == "Records":
        render_records()
    elif page == "Budget Entry":
        render_budget_entry()
    elif page == "Worker Master":
        render_worker_master()
    elif page == "My Account":
        render_account()
    else:
        st.session_state.hr_page = "Home"
        render_home()
